diagnostic_module:
// Measurement-only counters. Not part of the adopted runtime.
pub const Stats = struct {
    initial_registered: u64 = 0,
    memory_address_entries: u64 = 0,
    read_cell_entries: u64 = 0,
    write_cell_entries: u64 = 0,
    cell_writes_no_registry: u64 = 0,
    written_entries: u64 = 0,
    written_early_return: u64 = 0,
    written_nonempty: u64 = 0,
    linear_notifications: u64 = 0,
    indexed_notifications: u64 = 0,
    notify_attempts: u64 = 0,
    overlapping_notifications: u64 = 0,
    exact_cell_notifications: u64 = 0,
    partial_notifications: u64 = 0,
    index_rebuilds: u64 = 0,
};
pub var stats: Stats = .{};
pub var emit_enabled: bool = false;
pub fn reset(count: u64) void { stats = .{ .initial_registered = count }; }

counter_test_source:
const std = @import("std");
const support = @import("support.zig");
const registry = @import("../core/address_registry.zig");
const diag = @import("../core/memory_diagnostics.zig");
test "measurement counters distinguish cold linear indexed partial and repair paths" {
    var output = support.Output{};
    const machine = try support.createMachine(&output);
    defer support.destroyMachine(machine);
    try machine.interpretLine("AVARIABLE MEASURE-P");
    try std.testing.expectEqual(@as(usize, 1), machine.addresses.count);
    const slot = machine.words[try machine.lookupOrFail("MEASURE-P")].value;
    machine.in_counted = true;
    defer machine.in_counted = false;
    for ([_]bool{ true, false, true }) |full| {
        machine.addresses.index_dirty = true;
        machine.addresses.stable_writes = 0;
        diag.reset(1);
        for (0..100) |_| registry.written(machine, slot, if (full) 8 else 1, full);
        try std.testing.expectEqual(@as(u64, 100), diag.stats.written_entries);
        try std.testing.expectEqual(@as(u64, 32), diag.stats.linear_notifications);
        try std.testing.expectEqual(@as(u64, 68), diag.stats.indexed_notifications);
        try std.testing.expectEqual(@as(u64, 1), diag.stats.index_rebuilds);
        try std.testing.expectEqual(@as(u64, 100), diag.stats.notify_attempts);
        try std.testing.expectEqual(@as(u64, 100), diag.stats.overlapping_notifications);
        try std.testing.expectEqual(@as(u64, if (full) 100 else 0), diag.stats.exact_cell_notifications);
        try std.testing.expectEqual(@as(u64, if (full) 0 else 100), diag.stats.partial_notifications);
        try std.testing.expectEqual(if (full) registry.Status.valid else registry.Status.damaged, machine.addresses.records[0].status);
    }
}

